def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = {
        r for r in range(h)
        if all(v == grid[r][0] for v in grid[r])
    }
    sep_cols = {
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    }

    def segments(length, separators):
        result = []
        start = 0
        for i in range(length):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_blocks = segments(h, sep_rows)
    col_blocks = segments(w, sep_cols)

    non_separator = [
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    ]
    background = max(set(non_separator), key=non_separator.count)
    marker_colors = [v for v in set(non_separator) if v != background]
    marker = marker_colors[0] if marker_colors else None

    output = []
    for r0, r1 in row_blocks:
        row = []
        for c0, c1 in col_blocks:
            count = sum(
                grid[r][c] == marker
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if count > 1 else background)
        output.append(row)
    return output
